import type { Metadata } from "next";

/**
 * Site URL for canonical / Open Graph / sitemap URLs — `NEXT_PUBLIC_SITE_URL` (see .env.example), no trailing slash.
 * Kept free of `@/` imports so `scripts/og.ts` can read OG_PAGES with plain Node.
 */
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || "http://localhost:3000").replace(/\/+$/, "");
export const SITE_NAME = "COACH";
export const OG_SIZE = { width: 1200, height: 630 };

/**
 * Static Open Graph cards (public/og/<key>.jpg, 1200×630) — generated by `npm run og` from these entries + the product
 * cut-outs. Products get public/og/products/<slug>.jpg.
 */
export const OG_PAGES = {
  home: { eyebrow: "AUTUMN CHAPTER 2026", title: "Carried Through Every Chapter", images: ["/images/home/bag-signature-pink.png", "/images/home/bag-black.png", "/images/home/bag-bow-pink.png"] },
  "new-arrivals": { eyebrow: "JUST IN", title: "New Arrivals", images: ["/images/products/nolita-pink.png", "/images/products/tabby-quilted.png", "/images/products/city-tote.png"] },
  women: { eyebrow: "WOMEN", title: "Women’s Bags & Small Leather", images: ["/images/products/city-tote.png", "/images/products/tabby-quilted.png", "/images/home/bag-bow-pink.png"] },
  men: { eyebrow: "MEN", title: "Men’s Bags & Small Leather", images: ["/images/products/backpack.png", "/images/products/messenger.png", "/images/products/briefcase.png"] },
  bags: { eyebrow: "FOR HER & FOR HIM", title: "Bags for Women & Men", images: ["/images/products/cargo-tote.png", "/images/products/duffle.png", "/images/products/nolita-pink.png"] },
  "client-care": { eyebrow: "CLIENT CARE", title: "Here for Every Chapter", images: ["/images/products/tabby-quilted.png"] },
  "the-house": { eyebrow: "THE HOUSE · SINCE 1941", title: "Made by Hand, Made to Last", images: ["/images/products/messenger.png", "/images/products/city-tote.png", "/images/home/bag-signature-pink.png"] },
} as const;
export type OgPage = keyof typeof OG_PAGES;

export const ogImagePath = (key: OgPage) => `/og/${key}.jpg`;
export const productOgImagePath = (slug: string) => `/og/products/${slug}.jpg`;

/**
 * Canonical + Open Graph + Twitter for an indexable page. `path` is the clean URL (no filter / sort params), so
 * `/women?type=totes&sort=price-asc` canonicalises to `/women`. Relative URLs resolve against `metadataBase`.
 */
export function pageMetadata({
  title,
  description,
  path,
  image,
  imageAlt,
  absoluteTitle = false,
  type = "website",
}: {
  title: string;
  description: string;
  path: string;
  image: string;
  imageAlt: string;
  absoluteTitle?: boolean;
  type?: "website" | "article";
}): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;
  const images = [{ url: image, ...OG_SIZE, alt: imageAlt }];
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: { type, siteName: SITE_NAME, locale: "en_US", url: path, title: fullTitle, description, images },
    twitter: { card: "summary_large_image", title: fullTitle, description, images },
  };
}
